={{ (() => {
  const req = $('When Executed by Another Workflow').first().json;
  const info = $json;
  const place = [info.listing_title, info.listing_reference ? `ref ${info.listing_reference}` : null].filter(Boolean).join(', ');
  const attendees = [info.contact_email, info.agent_email].filter(Boolean).map((email) => ({ email }));
  return JSON.stringify({
    summary: `Property viewing — ${info.contact_name || 'client'}${info.listing_title ? ` — ${info.listing_title}` : ''}`,
    location: info.listing_address || undefined,
    description: [
      place ? `Property: ${place}` : null,
      info.listing_address ? `Address: ${info.listing_address}` : null,
      info.agent_name ? `Agent: ${info.agent_name}` : null,
      req.notes || null,
    ].filter(Boolean).join('\n'),
    start: { dateTime: req.starts_at, timeZone: info.timezone },
    end: { dateTime: req.ends_at, timeZone: info.timezone },
    attendees,
  });
})() }}

